import{z as A,x as l,o as e,c as d,q as o,j as s,D as B,d as t,s as r,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"需求系统资产定价","description":"","frontmatter":{"title":"需求系统资产定价","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/demand-system-asset-pricing.md","filePath":"econ/demand-system-asset-pricing.md","lastUpdated":1791413859000}'),p={name:"econ/demand-system-asset-pricing.md"};function m(C,E,D,c,F,u){const n=l("Mermaid");return e(),d("div",null,[E[2]||(E[2]=o('<h1 id="需求系统资产定价" tabindex="-1">需求系统资产定价 <a class="header-anchor" href="#需求系统资产定价" aria-label="Permalink to &quot;需求系统资产定价&quot;">​</a></h1><div class="epigraph"><p>价格出清的是各类投资者的份额需求；弹性有限时，供给与份额变动直接进入价格，不必先经过一个代表性核。</p><footer>—— Koijen and Yogo, A Demand System Approach to Asset Pricing, Journal of Political Economy, 2019</footer></div><p><a href="/econ/safe-asset-convenience">上一课</a>把便利写成服务流，家庭仍可被加总进一个带影子价格的 \\(m\\)。本课缺口是<strong>放弃代表性需求</strong>：机构、家庭、外资各有自己的份额方程，特征（市值、票息、评级、便利）进入需求，市场出清把特征的价格（因子）解出来。不估计 Koijen–Yogo 的系数，不把需求系统写成因子回归赛马。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CAPM / Lucas / 中介模型都先指定谁优化、再加总。需求系统反过来：在资产截面上写</p> \\[\\text{份额}_{i,j}= \\text{特征}_{j}\\cdot\\text{弹性}_{i}+\\text{潜在需求}, \\]<p>出清 \\(\\sum_i\\text{份额}_{i,j}=1\\)。弹性有限意味着资产不是完美替代——与 LOP 不冲突，因为不同资产的特征不同，不是同一 \\(x\\)。缺口是：时变溢价、便利、约束，都可以表现为某类投资者弹性有限、份额被迫调。供给（发行、回购、国债存量）直接移动价格。代表性 \\(m\\) 仍可以存在于后台，但不是操作上的加总起点。</p><p>这与 <a href="/econ/to-limit-order-book">到限价簿</a> 的切点：需求系统仍是均衡份额，没有队列。它回答「谁在持有」，不回答「单子怎么排」。</p><p><span class="marginnote">术语翻译：需求系统就是「不猜每个人心里的效用函数，直接给每类投资者立一张购物清单」——清单上写明：估值便宜 1 个点你会多买多少、评级降一级你会少买多少。这些「多少」就是弹性；把所有人的清单加起来正好买完市场上所有份额，价格就被解出来了。</span></p><p><span class="marginnote">Koijen and Yogo, <em>JPE</em> 127(4), 2019。特征需求来自产业组织的 logit 需求在资产上的移植。识别靠工具（例如基准指数纳入的外生部分），那是计量，本课只留结构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把投资者分类。每类对特征的弹性不同：养老金或保险可能对久期与评级极敏感（监管、负债），对便利与保证金敏感的是经销商。出清把特征的影子价格变成「因子」。中介约束紧 = 经销商弹性变或潜在需求降；便利升 = 国债特征的系数变。需求系统是上一课序摩擦的<strong>加总语言</strong>，不是否定 SDF：若弹性来自均值方差，回头仍可译成 \\(m\\)；若弹性来自制度，译出来的 \\(m\\) 含约束乘子。</p>',12)),(e(),s(i,null,{default:B(()=>[r(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20TYP%5B%22%E5%90%84%E7%B1%BB%E6%8A%95%E8%B5%84%E8%80%85%E9%9C%80%E6%B1%82%22%5D%20--%3E%20CLR%5B%22%E4%BB%BD%E9%A2%9D%E5%87%BA%E6%B8%85%22%5D%0A%20%20FEAT%5B%22%E8%B5%84%E4%BA%A7%E7%89%B9%E5%BE%81%22%5D%20--%3E%20TYP%0A%20%20CLR%20--%3E%20PR%5B%22%E4%BB%B7%E6%A0%BC%20%2F%20%E9%9A%90%E5%90%AB%E5%9B%A0%E5%AD%90%22%5D%0A%20%20CONS%5B%22%E7%BA%A6%E6%9D%9F%E4%B8%8E%E4%BE%BF%E5%88%A9%22%5D%20--%3E%20TYP%0A%20%20PR%20--%3E%20SDF%5B%22%E5%8F%AF%E8%AF%91%E5%9B%9E%20m%2C%20%E4%BD%86%E4%B8%8D%E4%BB%8E%E4%BB%A3%E8%A1%A8%E4%B8%BB%E4%BD%93%E8%B5%B7%E6%AD%A5%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"不要把「特征」写成 Fama–French 的排序。那里特征是为了投影平均收益；这里特征进入需求，价格是均衡产出。精神上更接近特征定价的一般均衡，而不是横截面检验手册。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"机制是有限替代加份额冲击。某类投资者被迫卖（赎回、监管、指数剔除），弹性有限的买方要求价格跌才吸收。跌多少由需求弹性决定，不由 \\(u'(c)\\) 直接决定——除非那一类恰好是代表性消费者。安全资产存量冲击是一类供给移动；中介去杠杆是一类需求移动。信息：若某类是知情者，份额里含 GS 采集；需求系统可以容纳，但默认版本常常是特征加噪声，把信息藏进残差。本课点明即可，不重做 REE。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"有限弹性是对「无限套利资本」的拒绝，与 Shleifer–Vishny 同方向，但这里不必行为偏差：制度分割足够。")],-1)),E[7]||(E[7]=a("p",null,[a("span",{class:"marginnote"},"数字实例：指数剔除迫使某类投资者卖掉 2% 的份额；接盘方弹性 0.5——价格每跌 1%，他们只肯多买 0.5%。要把 2% 全部吸收，价格约跌 \\(2\\%/0.5=4\\%\\)。同样的冲击若砸在弹性为 2 的市场上，只跌 1%：「谁在场上接货」比「跌了多少利空」更能定价格。")],-1)),(e(),s(i,null,{default:B(()=>[r(n,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22%E4%BB%BD%E9%A2%9D%E5%86%B2%E5%87%BB%EF%BC%9A%E6%9F%90%E7%B1%BB%E8%A2%AB%E8%BF%AB%E5%8D%96%E5%87%BA%22%5D%20--%3E%20ABS%7B%22%E4%B9%B0%E6%96%B9%E9%9C%80%E6%B1%82%E5%BC%B9%E6%80%A7%EF%BC%9F%22%7D%0A%20%20ABS%20--%3E%7C%22%E5%BC%B9%E6%80%A7%E5%85%85%E8%B6%B3%22%7C%20EAT%5B%22%E4%BB%B7%E6%A0%BC%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8A%A8%EF%BC%8C%E7%85%A7%E4%BB%B7%E6%8E%A5%E8%B4%A7%22%5D%0A%20%20ABS%20--%3E%7C%22%E5%BC%B9%E6%80%A7%E6%9C%89%E9%99%90%22%7C%20DEM%5B%22%E8%A6%81%E6%B1%82%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%B7%8C%E6%89%8D%E8%82%AF%E5%90%B8%E6%94%B6%22%5D%0A%20%20DEM%20--%3E%20MAG%5B%22%E8%B7%8C%E5%B9%85%20%E2%89%88%20%E5%86%B2%E5%87%BB%E9%87%8F%20%C3%B7%20%E4%B9%B0%E6%96%B9%E5%BC%B9%E6%80%A7%22%5D%0A%20%20MAG%20--%3E%20WHO%7B%22%E5%BC%B9%E6%80%A7%E6%8F%A1%E5%9C%A8%E8%B0%81%E6%89%8B%E9%87%8C%EF%BC%9F%22%7D%0A%20%20WHO%20--%3E%7C%22%E5%8F%97%E7%BA%A6%E6%9D%9F%E7%9A%84%E7%BB%8F%E9%94%80%E5%95%86%22%7C%20TIGHT%5B%22%E4%B8%AD%E4%BB%8B%E7%BA%A6%E6%9D%9F%E7%B4%A7%EF%BC%9A%E8%B7%8C%E5%B9%85%E6%94%BE%E5%A4%A7%22%5D%0A%20%20WHO%20--%3E%7C%22%E9%95%BF%E6%9C%9F%E8%B5%84%E9%87%91%22%7C%20SOFT%5B%22%E8%B7%8C%E5%B9%85%E6%B8%A9%E5%92%8C%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课序「摩擦与中介」在此结束。下一单元换数学装置：连续时间、伊藤、Merton 组合。需求系统不依赖连续时间；连续时间组合也不依赖机构份额。两课序在「谁的一阶条件决定 \\(m\\)」上相切：Merton 先写单人最优，再加总；需求系统先写加总需求。读连续时间时，默认无摩擦单人；要把约束加回去，回看本课序。</p><p>后课默认：有限弹性的份额需求使供给与机构流动进入价格。SDF 仍可翻译，但操作上不必从代表性 \\(c\\) 起步。不是 LOB，不是 CAPM 实证表。</p><p><span class="marginnote">常见误区：初学者容易把本课当成 CAPM 的另一种回归跑法。CAPM/因子回归把特征当「预测平均收益的变量」；需求系统把特征写进需求方程、价格是出清解出来的均衡产出。方向相反：前者从价格反推，后者从需求正推价格——同一些数据，问题不是同一个。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>需求系统：各类份额对特征的弹性有限，出清决定价格。</li><li>约束、便利、供给冲击表现为需求或特征移动。</li><li>可译成带乘子的 \\(m\\)，加总起点不是代表性消费。</li><li>出处：Koijen and Yogo, <em>JPE</em> 2019。</li></ul>',6))])}const P=A(p,[["render",m]]);export{h as __pageData,P as default};
